def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    ox, oy = observation.get("opponent_position", (sx, sy))
    width = observation.get("grid_width", 1)
    height = observation.get("grid_height", 1)

    # Helper to compute move toward a target
    def move_toward(tx, ty):
        dx = 0
        dy = 0
        if tx > sx:
            dx = 1
        elif tx < sx:
            dx = -1
        if ty > sy:
            dy = 1
        elif ty < sy:
            dy = -1
        return dx, dy

    # Pursuit-evasion behavior
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return list(move_toward(ox, oy))
        corners = [
            [0, 0],
            [0, height - 1],
            [width - 1, 0],
            [width - 1, height - 1],
        ]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return list(move_toward(target[0], target[1]))

    # Territory control behavior
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if targets:
            best = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
            return list(move_toward(best[0], best[1]))
        else:
            return [0, 0]

    # Resource collection behavior
    resources = observation.get("resources") or []
    if resources:
        best = min(resources, key=lambda r: abs(r[0] - sx) + abs(r[1] - sy))
        return list(move_toward(best[0], best[1]))
    else:
        # No resources: stay or move towards opponent
        return list(move_toward(ox, oy))

